// Render the live tracking card (start/stop + elapsed time).
export function TrackerCard({
  categories,
  activeDate,
}: {
  categories: CategoryModel[];
  activeDate: string;
}) {
  const router = useRouter();
  const defaultCategoryId = useMemo(() => categories[0]?.id ?? "", [categories]);

  const [active, setActive] = useState<SessionWithCategory | null>(null);
  const [categoryId, setCategoryId] = useState(defaultCategoryId);
  const [title, setTitle] = useState("");
  const [activityQuery, setActivityQuery] = useState("");
  const [createActivityOpen, setCreateActivityOpen] = useState(false);
  const [startTime, setStartTime] = useState("");
  const [timeZone, setTimeZone] = useState("Asia/Yerevan");
  const [isBusy, setIsBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());
  const tickRef = useRef<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    const load = () => {
      fetchActiveTimer()
        .then((s) => {
          if (!cancelled) {
            setError(null);
            setActive(s);
          }
        })
        .catch((e) => {
          if (!cancelled) setError(e instanceof Error ? e.message : "Failed to load timer.");
        });
    };
    load();
    const unsub = subscribeActiveTimerRefresh(load);
    return () => {
      cancelled = true;
      unsub();
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    fetchDefaultTimeZone()
      .then((tz) => {
        if (!cancelled) setTimeZone(tz);
      })
      .catch(() => {
        // Keep fallback timezone.
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!active?.startedAt) return;
    tickRef.current = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      if (tickRef.current) window.clearInterval(tickRef.current);
      tickRef.current = null;
    };
  }, [active?.startedAt]);

  const elapsedSeconds = (() => {
    if (!active?.startedAt) return 0;
    const start = new Date(active.startedAt).getTime();
    if (Number.isNaN(start)) return 0;
    return Math.max(0, Math.floor((now - start) / 1000));
  })();

  function applyActivitySelection(activity: ActivitySelection) {
    setTitle(activity.title);
    setCategoryId(activity.categoryId);
    setActivityQuery(activity.title);
  }

  function clearActivityPrefill() {
    setTitle("");
    setCategoryId(defaultCategoryId);
    setActivityQuery("");
  }

  async function onStart() {
    setError(null);
    if (!categoryId) return setError("Category is required.");
    if (!categories.length) return setError("No categories available.");
    if (!timeZone.trim()) return setError("Timezone is required.");
    const tz = timeZone.trim();
    let startedAtIso: string | undefined;
    if (startTime.trim()) {
      const iso = ymdAndHmToUtcIsoInTimeZone(activeDate, startTime.trim(), tz);
      if (!iso) {
        setError("Invalid start time, date, or timezone.");
        return;
      }
      if (new Date(iso).getTime() > Date.now() + 60_000) {
        setError("Start time cannot be in the future.");
        return;
      }
      startedAtIso = iso;
    }

    try {
      setIsBusy(true);
      const created = await startTimer({
        categoryId,
        title: title.trim() ? title.trim() : null,
        timeZone: tz,
        ...(startedAtIso ? { startedAt: startedAtIso } : {}),
      });
      setActive(created);
      setTitle("");
      setActivityQuery("");
      setStartTime("");
      router.refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to start timer.");
    } finally {
      setIsBusy(false);
    }
  }

  async function onStop() {
    setError(null);
    if (!active?.id) return;
    try {
      setIsBusy(true);
      await stopTimer(active.id);
      setActive(null);
      router.refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to stop timer.");
    } finally {
      setIsBusy(false);
    }
  }

  const activeCategoryName = active?.category?.name ?? null;

  return (
    <div className="w-full max-w-md rounded-xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-black">
      <div className="flex items-center justify-between">
        <div className="text-sm font-semibold text-zinc-900 dark:text-zinc-50">
          Tracker
        </div>
        {active ? (
          <div className="rounded-md bg-emerald-50 px-2 py-1 text-[11px] font-medium text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200">
            Running
          </div>
        ) : (
          <div className="rounded-md bg-zinc-50 px-2 py-1 text-[11px] font-medium text-zinc-700 dark:bg-zinc-950 dark:text-zinc-300">
            Idle
          </div>
        )}
      </div>

      <div className="mt-3 flex flex-col gap-3">
        {active ? (
          <>
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0 flex flex-col gap-1 text-xs text-zinc-600 dark:text-zinc-400">
                <div>
                  {activeCategoryName ? `Category: ${activeCategoryName}` : "Category: —"}
                </div>
                <div
                  className="truncate"
                  title={active.title?.trim() ? active.title.trim() : undefined}
                >
                  {active.title?.trim() ? `Title: ${active.title.trim()}` : "Title: —"}
                </div>
              </div>
              <div className="shrink-0 font-mono text-sm text-zinc-900 dark:text-zinc-50">
                {formatDuration(elapsedSeconds)}
              </div>
            </div>
            <button
              type="button"
              disabled={isBusy}
              onClick={onStop}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-red-600 px-4 text-sm font-medium text-white hover:bg-red-500 disabled:opacity-50"
            >
              {isBusy ? "Stopping..." : "Stop"}
            </button>
          </>
        ) : (
          <>
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Activity
              </label>
              <ActivityCombobox
                value={activityQuery}
