const subscribeToHydration = () => () => {};
const getHydratedSnapshot = () => true;
const getServerHydratedSnapshot = () => false;

type PomodoroContextValue = {
  state: PomodoroState;
  isHydrated: boolean;
  start: () => void;
  stop: () => void;
  skip: () => void;
  updateSettings: (partial: Partial<PomodoroSettings>) => void;
  notificationStatus: PomodoroNotificationStatus;
  requestNotificationPermission: () => Promise<PomodoroNotificationStatus>;
  reportNotificationFailure: () => void;
  subscribePhaseComplete: (
    fn: (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void,
  ) => () => void;
};

export const PomodoroContext = createContext<PomodoroContextValue | null>(null);

type InitialPomodoroState = {
  state: PomodoroState;
  phaseCompleted: ActivePomodoroPhase | null;
};

export function PomodoroProvider({ children }: { children: ReactNode }) {
  const isHydrated = useSyncExternalStore(
    subscribeToHydration,
    getHydratedSnapshot,
    getServerHydratedSnapshot,
  );
  const [initialState] = useState<InitialPomodoroState>(() => {
    const settings = loadPomodoroSettings();
    const loaded = loadPomodoroRun(settings);
    return hydratePomodoroState(loaded, Date.now());
  });
  const [state, setState] = useState<PomodoroState>(initialState.state);
  const [notificationStatus, setNotificationStatus] =
    useState<PomodoroNotificationStatus>(() => getPomodoroNotificationStatus());
  const initialPhaseCompletion = useRef(
    initialState.phaseCompleted
      ? {
          completedPhase: initialState.phaseCompleted,
          nextPhase: initialState.state.phase,
        }
      : null,
  );
  const phaseCompleteListeners = useRef(
    new Set<(phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void>(),
  );

  useEffect(() => {
    savePomodoroSettings(state.settings);
  }, [state.settings]);

  useEffect(() => {
    savePomodoroRun(state);
  }, [state]);

  const emitPhaseComplete = useCallback(
    (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => {
      for (const fn of phaseCompleteListeners.current) fn(phase, nextPhase);
    },
    [],
  );

  useEffect(() => {
    const completion = initialPhaseCompletion.current;
    if (!completion) return;

    initialPhaseCompletion.current = null;
    queueMicrotask(() =>
      emitPhaseComplete(completion.completedPhase, completion.nextPhase),
    );
  }, [emitPhaseComplete]);

  useEffect(() => {
    if (!state.isRunning) return;

    const id = window.setInterval(() => {
      setState((current) => {
        const result = tick(current, Date.now());
        if (result.phaseCompleted) {
          queueMicrotask(() =>
            emitPhaseComplete(result.phaseCompleted!, result.state.phase),
          );
        }
        return result.state;
      });
    }, 1000);

    return () => window.clearInterval(id);
  }, [state.isRunning, emitPhaseComplete]);

  useEffect(() => {
    function handleStorage(event: StorageEvent) {
      if (event.key !== RUN_KEY) return;

      const settings = loadPomodoroSettings();
      const incoming = event.newValue
        ? loadPomodoroRun(settings)
        : createInitialState(settings);
      const result = hydratePomodoroState(incoming, Date.now());

      if (result.phaseCompleted) {
        queueMicrotask(() =>
          emitPhaseComplete(result.phaseCompleted!, result.state.phase),
        );
      }
      setState(result.state);
    }

    window.addEventListener("storage", handleStorage);
    return () => window.removeEventListener("storage", handleStorage);
  }, [emitPhaseComplete]);

  const handleStart = useCallback(() => {
    setState((current) => {
      return start(current);
    });
  }, []);

  const handleStop = useCallback(() => {
    setState((current) => {
      return stop(current);
    });
  }, []);

  const handleSkip = useCallback(() => {
    setState((current) => skip(current).state);
  }, []);

  const handleUpdateSettings = useCallback((partial: Partial<PomodoroSettings>) => {
    setState((current) => updateSettings(current, partial));
  }, []);

  const handleRequestNotificationPermission = useCallback(async () => {
    const status = await requestPomodoroNotificationPermission();
    setNotificationStatus(status);
    return status;
  }, []);

  const reportNotificationFailure = useCallback(() => {
    setNotificationStatus("error");
  }, []);

  const subscribePhaseComplete = useCallback(
    (fn: (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void) => {
      phaseCompleteListeners.current.add(fn);
      return () => {
        phaseCompleteListeners.current.delete(fn);
      };
    },
    [],
  );

  const value = useMemo(
    () => ({
      state,
      isHydrated,
      start: handleStart,
      stop: handleStop,
      skip: handleSkip,
      updateSettings: handleUpdateSettings,
      notificationStatus,
      requestNotificationPermission: handleRequestNotificationPermission,
      reportNotificationFailure,
      subscribePhaseComplete,
    }),
    [
      state,
      isHydrated,
      handleStart,
      handleStop,
      handleSkip,
      handleUpdateSettings,
      notificationStatus,
      handleRequestNotificationPermission,
      reportNotificationFailure,
      subscribePhaseComplete,
    ],
  );

  return (
    <PomodoroContext.Provider value={value}>
      <PomodoroPhaseNotification />
      <PomodoroPhaseAlert />
      {children}
    </PomodoroContext.Provider>
  );
}

import {
  app,
  BrowserWindow,
  dialog,
  type Event as ElectronEvent,
} from "electron";

import { createRuntimeConfig, type RuntimeConfig } from "./runtime-config.js";
import {
  DesktopRuntimeError,
  ServerProcess,
} from "./server-process.js";

let mainWindow: BrowserWindow | null = null;
let serverProcess: ServerProcess | null = null;
let runtimeConfig: RuntimeConfig | null = null;
let isQuitting = false;
let startupPromise: Promise<void> | null = null;
let isStarting = false;

export function isAllowedNavigation(origin: string, url: string): boolean {
  try {
    return new URL(url).origin === origin;
  } catch {
    return false;
  }
}

function focusMainWindow(): void {
  if (!mainWindow) {
    return;
  }
  if (mainWindow.isMinimized()) {
    mainWindow.restore();
  }
  mainWindow.focus();
}

function configureWindowSecurity(window: BrowserWindow, origin: string): void {
  const denyNavigation = (event: ElectronEvent, url: string) => {
    if (!isAllowedNavigation(origin, url)) {
      event.preventDefault();
    }
  };

  window.webContents.on("will-navigate", denyNavigation);
  window.webContents.on("will-redirect", denyNavigation);
  window.webContents.setWindowOpenHandler(() => ({ action: "deny" }));
}

async function createMainWindow(): Promise<void> {
  if (!runtimeConfig || !serverProcess?.isReady) {
    throw new Error("The desktop server is not ready for a window");
  }

  mainWindow = new BrowserWindow({
    show: false,
    width: 1280,
    height: 860,
    minWidth: 960,
    minHeight: 640,
    title: "NamehAmal",
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: true,
    },
  });
  configureWindowSecurity(mainWindow, runtimeConfig.origin);
  mainWindow.on("closed", () => {
    mainWindow = null;
  });

  try {
    await mainWindow.loadURL(runtimeConfig.origin);
    mainWindow.show();
  } catch (error) {
    mainWindow.destroy();
    mainWindow = null;
    throw new DesktopRuntimeError(
      "SERVER_CRASHED",
      `NamehAmal could not load its local dashboard. Check ${serverProcess.logPath ?? "the desktop log"} and try again.`,
      { cause: error },
    );
  }
}

function showStartupError(error: unknown): void {
  const message =
    error instanceof Error
      ? error.message
      : "The desktop application could not start for an unknown reason.";
  dialog.showErrorBox("NamehAmal could not start", message);
}

async function startApplication(): Promise<void> {
  isStarting = true;
  runtimeConfig = createRuntimeConfig({
    isPackaged: app.isPackaged,
    projectRoot: app.getAppPath(),
    resourcesPath: process.resourcesPath,
    userDataDirectory: app.getPath("userData"),
  });
  serverProcess = new ServerProcess({
    config: runtimeConfig,
    onUnexpectedExit: (error) => {
      if (isQuitting) {
        return;
      }
      showStartupError(error);
      app.quit();
    },
  });
  try {
    await serverProcess.start();
    await createMainWindow();
  } finally {
    isStarting = false;
  }
}

async function shutdown(): Promise<void> {
  await serverProcess?.stop();
  serverProcess = null;
}

const gotSingleInstanceLock = app.requestSingleInstanceLock();

if (!gotSingleInstanceLock) {
  app.quit();
} else {
  app.on("second-instance", () => {
    focusMainWindow();
  });

  app.whenReady().then(() => {
    startupPromise = startApplication().catch((error) => {
      showStartupError(error);
      void app.quit();
    });
    return startupPromise;
  });

  app.on("activate", () => {
    if (mainWindow) {
      focusMainWindow();
      return;
    }
    if (serverProcess?.isReady && !isStarting) {
      startupPromise = createMainWindow().catch((error) => {
        showStartupError(error);
        void app.quit();
      });
    }
  });

  app.on("window-all-closed", () => {
    if (!isQuitting) {
      app.quit();
    }
  });

  app.on("before-quit", (event) => {
    if (isQuitting) {
      return;
    }
    event.preventDefault();
    isQuitting = true;
    void shutdown().finally(() => {
      app.quit();
    });
  });
}

import { Prisma } from "@/app/generated/prisma/client";
import { offsetMinutesAt, isValidIanaTimeZone } from "@/app/lib/timezone";
import { getDefaultTimeZone } from "@/app/server/app-settings";
import { prisma } from "@/app/server/db";

export const runtime = "nodejs";

// Build a consistent JSON error response.
function jsonError(message: string, status = 400) {
  return Response.json({ ok: false, error: message }, { status });
}

// Parse a JSON body safely.
async function readJson(request: Request): Promise<unknown> {
  try {
    return await request.json();
  } catch {
    return null;
  }
}

// Parse an ISO date string safely.
function parseDate(value: string | null) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}

// Fetch a legacy in-flight TIMER Session row (older app versions).
async function getLegacyActiveTimerSession() {
  return prisma.session.findFirst({
    where: { kind: "TIMER", endedAt: null },
    orderBy: [{ startedAt: "desc" }, { createdAt: "desc" }],
    include: { category: true },
  });
}

// Fetch the draft live timer row (not listed in Session until stop).
async function getDraftActiveTimer() {
  return prisma.activeTimer.findFirst({
    orderBy: [{ createdAt: "desc" }],
    include: { category: true },
  });
}

// Map an ActiveTimer row to the Session-shaped JSON the tracker UI expects.
function draftActiveTimerToSessionShape(
  draft: Prisma.ActiveTimerGetPayload<{ include: { category: true } }>,
) {
  return {
    id: draft.id,
    kind: "TIMER" as const,
    title: draft.title,
    note: null as string | null,
    categoryId: draft.categoryId,
    category: draft.category,
    occurredAt: draft.startedAt,
    startedAt: draft.startedAt,
    endedAt: null as Date | null,
    durationSeconds: 0,
    timeZone: draft.timeZone,
    timeZoneOffsetMinutes: draft.timeZoneOffsetMinutes,
    createdAt: draft.createdAt,
    updatedAt: draft.updatedAt,
  };
}

// Resolve the current running timer for GET / start conflict checks (draft or legacy Session).
async function getActiveTimerForClient() {
  const draft = await getDraftActiveTimer();
  if (draft) return draftActiveTimerToSessionShape(draft);
  return getLegacyActiveTimerSession();
}

// Return the currently active timer session (or null).
export async function GET() {
  const active = await getActiveTimerForClient();
  return Response.json({ ok: true, data: active ?? null });
}

// Start/stop live tracking sessions.
export async function POST(request: Request) {
  const body = await readJson(request);
  if (!body || typeof body !== "object") return jsonError("Invalid JSON body.");

  const action =
    "action" in body && typeof body.action === "string" ? body.action : null;

  if (action === "start") {
    const categoryId =
      "categoryId" in body && typeof body.categoryId === "string"
        ? body.categoryId.trim()
        : "";
    const title =
      "title" in body && typeof body.title === "string" ? body.title.trim() : "";
    const timeZoneRaw =
      "timeZone" in body && typeof body.timeZone === "string" ? body.timeZone.trim() : "";

    if (!categoryId) return jsonError("`categoryId` is required.");

    const category = await prisma.category.findUnique({ where: { id: categoryId } });
    if (!category) return jsonError("Category not found.", 404);

    const defaultTimeZone = await getDefaultTimeZone();
    const timeZone = timeZoneRaw ? timeZoneRaw : defaultTimeZone;
    if (!isValidIanaTimeZone(timeZone)) {
      return jsonError("`timeZone` must be a valid IANA timezone (e.g. \"Asia/Yerevan\").");
    }

    const existing = await getActiveTimerForClient();
    if (existing) {
      return Response.json(
        { ok: false, error: "A timer session is already running.", data: existing },
        { status: 409 },
      );
    }

    const startedAtRaw =
      "startedAt" in body && typeof body.startedAt === "string" ? body.startedAt.trim() : "";
    const nowMs = Date.now();

  const nowMs = Date.now();
  const futureSlackMs = 60_000;

  let startedAt = new Date();
  if (startedAtRaw) {
    const parsed = parseDate(startedAtRaw);
    if (!parsed) return jsonError("`startedAt` must be a valid ISO date.");
    if (parsed.getTime() > nowMs + futureSlackMs) {
      return jsonError("`startedAt` cannot be in the future.");
    }
    startedAt = parsed;
  }

  const timeZoneOffsetMinutes = offsetMinutesAt(startedAt, timeZone);

  try {
    const created = await prisma.activeTimer.create({
      data: {
        title: title || null,
        categoryId,
        timeZone,
        startedAt,
        timeZoneOffsetMinutes,
      },
      include: { category: true },
    });

    return Response.json(
      { ok: true, data: draftActiveTimerToSessionShape(created) },
      { status: 201 },
    );
  } catch (err) {
    if (err instanceof Prisma.PrismaClientKnownRequestError) {
      return jsonError("Failed to start timer session.", 400);
    }
    return jsonError("Failed to start timer session.", 500);
  }
}

if (action === "stop") {
  const sessionId =
    "sessionId" in body && typeof body.sessionId === "string"
      ? body.sessionId.trim()
      : "";

  if (!sessionId) return jsonError("`sessionId` is required.");

  const draft = await prisma.activeTimer.findUnique({
    where: { id: sessionId },
    include: { category: true },
  });

  if (draft) {
    const endedAt = new Date();
    const durationSeconds = Math.max(
      1,
      Math.floor((endedAt.getTime() - draft.startedAt.getTime()) / 1000),
    );

    try {
      const finalized = await prisma.$transaction(async (tx) => {
        const created = await tx.session.create({
          data: {
            kind: "TIMER",
            title: draft.title,
            note: null,
            categoryId: draft.categoryId,
            occurredAt: draft.startedAt,
            startedAt: draft.startedAt,
            endedAt,
            durationSeconds,
            timeZone: draft.timeZone,
            timeZoneOffsetMinutes: draft.timeZoneOffsetMinutes,
          },
          include: { category: true },
        });
        await tx.activeTimer.delete({ where: { id: draft.id } });
        return created;
      });

      return Response.json({ ok: true, data: finalized });
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError) {
        if (err.code === "P2025") return jsonError("Timer session not found.", 404);
        return jsonError("Failed to stop timer session.", 400);
      }
      return jsonError("Failed to stop timer session.", 500);
    }
  }

  const session = await prisma.session.findUnique({
    where: { id: sessionId },
    include: { category: true },
  });
  if (!session) return jsonError("Session not found.", 404);
  if (session.kind !== "TIMER") return jsonError("Session is not a TIMER session.", 400);
  if (!session.startedAt) return jsonError("TIMER session is missing `startedAt`.", 400);
  if (session.endedAt) {
    return jsonError("Timer session is already stopped.", 409);
  }

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import type { CategoryModel } from "@/app/generated/prisma/models";
import { ActivityCombobox, type ActivitySelection } from "@/app/components/ActivityCombobox";
import { subscribeActiveTimerRefresh } from "@/app/dashboard/active-timer-refresh-bus";
import { formatDuration } from "@/app/dashboard/format";
import { toActivitySelection } from "@/app/lib/use-activities";
import {
  fetchActiveTimer,
  fetchDefaultTimeZone,
  startTimer,
  stopTimer,
  type SessionWithCategory,
} from "@/app/lib/tracker-client";
import { ymdAndHmToUtcIsoInTimeZone } from "@/app/lib/timezone";
import { ActivityFormDialog } from "@/app/settings/ActivityFormDialog";

// Render the live tracking card (start/stop + elapsed time).
export function TrackerCard({
  categories,
  activeDate,
}: {
  categories: CategoryModel[];
  activeDate: string;
}) {
  const router = useRouter();
  const defaultCategoryId = useMemo(() => categories[0]?.id ?? "", [categories]);

  const [active, setActive] = useState<SessionWithCategory | null>(null);
  const [categoryId, setCategoryId] = useState(defaultCategoryId);
  const [title, setTitle] = useState("");
  const [activityQuery, setActivityQuery] = useState("");
  const [createActivityOpen, setCreateActivityOpen] = useState(false);
  const [startTime, setStartTime] = useState("");
  const [timeZone, setTimeZone] = useState("Asia/Yerevan");
  const [isBusy, setIsBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());
  const tickRef = useRef<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    const load = () => {
      fetchActiveTimer()
        .then((s) => {
          if (!cancelled) {
            setError(null);
            setActive(s);
          }
        })
        .catch((e) => {
          if (!cancelled) setError(e instanceof Error ? e.message : "Failed to load timer.");
        });
    };
    load();
    const unsub = subscribeActiveTimerRefresh(load);
    return () => {
      cancelled = true;
      unsub();
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    fetchDefaultTimeZone()
      .then((tz) => {
        if (!cancelled) setTimeZone(tz);
      })
      .catch(() => {
        // Keep fallback timezone.
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!active?.startedAt) return;
    tickRef.current = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      if (tickRef.current) window.clearInterval(tickRef.current);
      tickRef.current = null;
    };
  }, [active?.startedAt]);

  const elapsedSeconds = (() => {
    if (!active?.startedAt) return 0;
    const start = new Date(active.startedAt).getTime();
    if (Number.isNaN(start)) return 0;
    return Math.max(0, Math.floor((now - start) / 1000));
  })();

  function applyActivitySelection(activity: ActivitySelection) {
    setTitle(activity.title);
    setCategoryId(activity.categoryId);
    setActivityQuery(activity.title);
  }

  function clearActivityPrefill() {
    setTitle("");
    setCategoryId(defaultCategoryId);
    setActivityQuery("");
  }

  async function onStart() {
    setError(null);
    if (!categoryId) return setError("Category is required.");
    if (!categories.length) return setError("No categories available.");
    if (!timeZone.trim()) return setError("Timezone is required.");
    const tz = timeZone.trim();
    let startedAtIso: string | undefined;
    if (startTime.trim()) {
      const iso = ymdAndHmToUtcIsoInTimeZone(activeDate, startTime.trim(), tz);
      if (!iso) {
        setError("Invalid start time, date, or timezone.");
        return;
      }
      if (new Date(iso).getTime() > Date.now() + 60_000) {
        setError("Start time cannot be in the future.");
        return;
      }
      startedAtIso = iso;
    }

    try {
      setIsBusy(true);
      const created = await startTimer({
        categoryId,
        title: title.trim() ? title.trim() : null,
        timeZone: tz,
        ...(startedAtIso ? { startedAt: startedAtIso } : {}),
      });
      setActive(created);
      setTitle("");
      setActivityQuery("");
      setStartTime("");
      router.refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to start timer.");
    } finally {
      setIsBusy(false);
    }
  }

  async function onStop() {
    setError(null);
    if (!active?.id) return;
    try {
      setIsBusy(true);
      await stopTimer(active.id);
      setActive(null);
      router.refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to stop timer.");
    } finally {
      setIsBusy(false);
    }
  }

  const activeCategoryName = active?.category?.name ?? null;

  return (
    <div className="w-full max-w-md rounded-xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-black">
      <div className="flex items-center justify-between">
        <div className="text-sm font-semibold text-zinc-900 dark:text-zinc-50">
          Tracker
        </div>
        {active ? (
          <div className="rounded-md bg-emerald-50 px-2 py-1 text-[11px] font-medium text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200">
            Running
          </div>
        ) : (
          <div className="rounded-md bg-zinc-50 px-2 py-1 text-[11px] font-medium text-zinc-700 dark:bg-zinc-950 dark:text-zinc-300">
            Idle
          </div>
        )}
      </div>

      <div className="mt-3 flex flex-col gap-3">
        {active ? (
          <>
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0 flex flex-col gap-1 text-xs text-zinc-600 dark:text-zinc-400">
                <div>
                  {activeCategoryName ? `Category: ${activeCategoryName}` : "Category: —"}
                </div>
                <div
                  className="truncate"
                  title={active.title?.trim() ? active.title.trim() : undefined}
                >
                  {active.title?.trim() ? `Title: ${active.title.trim()}` : "Title: —"}
                </div>
              </div>
              <div className="shrink-0 font-mono text-sm text-zinc-900 dark:text-zinc-50">
                {formatDuration(elapsedSeconds)}
              </div>
            </div>
            <button
              type="button"
              disabled={isBusy}
              onClick={onStop}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-red-600 px-4 text-sm font-medium text-white hover:bg-red-500 disabled:opacity-50"
            >
              {isBusy ? "Stopping..." : "Stop"}
            </button>
          </>
        ) : (
          <>
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Activity
              </label>
              <ActivityCombobox
                value={activityQuery}
                onValueChange={(next) => {
                  setActivityQuery(next);
                  if (!next.trim()) clearActivityPrefill();
                }}
                onSelect={applyActivitySelection}
                onClear={clearActivityPrefill}
                onCreateNew={() => setCreateActivityOpen(true)}
                placeholder="Search activities to pre-fill…"
                disabled={isBusy}
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Category
              </label>
              <select
                value={categoryId}
                onChange={(e) => setCategoryId(e.target.value)}
                className="h-10 rounded-lg border border-zinc-200 bg-white px-3 text-sm text-zinc-900 outline-none focus:ring-2 focus:ring-zinc-400 dark:border-zinc-800 dark:bg-black dark:text-zinc-50"
              >
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Title
              </label>
              <input
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Optional"
                className="h-10 rounded-lg border border-zinc-200 bg-white px-3 text-sm text-zinc-900 outline-none focus:ring-2 focus:ring-zinc-400 dark:border-zinc-800 dark:bg-black dark:text-zinc-50"
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Timezone
              </label>
              <input
                value={timeZone}
                onChange={(e) => setTimeZone(e.target.value)}
                placeholder='e.g. "Asia/Yerevan"'
                className="h-10 rounded-lg border border-zinc-200 bg-white px-3 text-sm text-zinc-900 outline-none focus:ring-2 focus:ring-zinc-400 dark:border-zinc-800 dark:bg-black dark:text-zinc-50"
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
                Start time (optional)
              </label>
              <input
                type="time"
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                className="h-10 rounded-lg border border-zinc-200 bg-white px-3 text-sm text-zinc-900 outline-none focus:ring-2 focus:ring-zinc-400 dark:border-zinc-800 dark:bg-black dark:text-zinc-50"
              />
              <p className="text-xs text-zinc-500 dark:text-zinc-400">
                Wall time on {activeDate} in the timezone above; leave empty to start from now.
              </p>
            </div>

            {error ? (
              <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-800 dark:border-red-900 dark:bg-red-950 dark:text-red-200">
                {error}
              </div>
            ) : null}

            <button
              type="button"
              disabled={isBusy || !categories.length}
              onClick={onStart}
              className="inline-flex h-10 items-center justify-center rounded-lg bg-zinc-900 px-4 text-sm font-medium text-white hover:bg-zinc-800 disabled:opacity-50 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200"
            >
              {isBusy ? "Starting..." : "Start"}
            </button>
          </>
        )}

        {active && error ? (
