    const wasIdle = this.state.phase === "idle" && !this.state.isRunning;
    this.applyEngineState(start(this.state, this.now()));
    if (wasIdle) {
      await this.bindTrackerDraft();
    }
    this.persist();
    this.broadcastNow();
    return this.state;
