  isRunning: false,
  completedFocusSessions: 0,
  settings: {
    focusSeconds: 1500,
    shortRestSeconds: 300,
    longRestSeconds: 900,
    longRestInterval: 4,
    notifyOnPhaseComplete: false,
  },
};

