// Shared IPC channel names and payload types for the desktop pomodoro feature.
// Renderer ↔ main contract: specs/002-mac-menubar-pomodoro/contracts/ipc.md
//
// This module must stay free of `electron` imports so the renderer can reuse the
// payload types (type-only imports are erased at build time).

import type { PomodoroSettings, PomodoroState } from "../app/lib/pomodoro/types.js";

export const IPC_CHANNELS = {
  getPomodoroState: "pomodoro:get-state",
  startPomodoro: "pomodoro:start",
  stopPomodoro: "pomodoro:stop",
  skipPomodoro: "pomodoro:skip",
  updatePomodoroSettings: "pomodoro:update-settings",
  reportSelectedActivity: "desktop:report-selected-activity",
  setReminderEnabled: "desktop:set-reminder-enabled",
  pomodoroStateChanged: "pomodoro:state-changed",
  reminderChanged: "desktop:reminder-changed",
} as const;

/** The app's "currently selected activity" as last reported by the renderer (data-model §3). */
export type SelectedActivityRef = {
  categoryId: string;
  title: string | null;
  reportedAt: number;
};

/** Full state snapshot pushed to the renderer and consumed by the Tray. */
export type PomodoroSnapshot = {
  state: PomodoroState;
  selectedActivity: SelectedActivityRef | null;
  reminderEnabled: boolean;
};

/** Activity label shown next to the tray countdown (draft title → category name → "—"). */
export const FALLBACK_ACTIVITY_NAME = "—";

/** API exposed on `window.namehAmalDesktop` by `electron/preload.ts` (contracts/ipc.md). */
export interface NamehAmalDesktop {
  getPomodoroState(): Promise<PomodoroSnapshot>;
  startPomodoro(): Promise<PomodoroState>;
  stopPomodoro(): Promise<PomodoroState>;
  skipPomodoro(): Promise<PomodoroState>;
  updatePomodoroSettings(partial: Partial<PomodoroSettings>): Promise<PomodoroState>;
  reportSelectedActivity(payload: { categoryId: string; title: string | null }): Promise<void>;
  setReminderEnabled(enabled: boolean): Promise<boolean>;
  onPomodoroStateChanged(listener: (snapshot: PomodoroSnapshot) => void): () => void;
  onReminderChanged(listener: (enabled: boolean) => void): () => void;
}

export function isValidSelectedActivityPayload(
  payload: unknown,
): payload is { categoryId: string; title: string | null } {
  if (typeof payload !== "object" || payload === null) return false;
  const record = payload as Record<string, unknown>;
  return (
    typeof record.categoryId === "string" &&
    record.categoryId.trim().length > 0 &&
    (record.title === null || typeof record.title === "string")
  );
}

// Desktop runtime state: load/validate/save `userData/pomodoro.json` (schema v1).
// Data model: specs/002-mac-menubar-pomodoro/data-model.md §4
//
// Any corrupt/missing/mismatched-version file yields defaults without crashing.
// Run-snapshot writes are debounced to at most 1 Hz.

import { promises as fs } from "node:fs";
import path from "node:path";

import {
  createInitialState,
  type PomodoroRunLike,
} from "./pomodoro-run.js";
import {
  parsePomodoroRun,
  parsePomodoroSettings,
} from "../app/lib/pomodoro/storage.js";
import type { PomodoroState } from "../app/lib/pomodoro/types.js";
import type { SelectedActivityRef } from "./ipc-channels.js";

export const DESKTOP_STATE_VERSION = 1;

export type DesktopRuntimeState = {
  version: typeof DESKTOP_STATE_VERSION;
  /** Persisted run snapshot (pre-validation); parse via `parsePomodoroRun`. */
  run: unknown;
  settings: unknown;
  selectedActivity: SelectedActivityRef | null;
  reminderEnabled: boolean;
};

export function createDefaultDesktopState(): DesktopRuntimeState {
  return {
    version: DESKTOP_STATE_VERSION,
    run: null,
    settings: null,
    selectedActivity: null,
    reminderEnabled: true,
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** Parse persisted selected-activity data; invalid → null. */
export function parseSelectedActivity(raw: unknown): SelectedActivityRef | null {
  if (!isRecord(raw)) return null;
  const categoryId =
    typeof raw.categoryId === "string" ? raw.categoryId.trim() : "";
  if (!categoryId) return null;
  const title =
    typeof raw.title === "string" && raw.title.length > 0 ? raw.title : null;
  const reportedAt =
    typeof raw.reportedAt === "number" && Number.isFinite(raw.reportedAt)
      ? Math.max(0, Math.floor(raw.reportedAt))
      : 0;
  return { categoryId, title, reportedAt };
}

/**
 * Parse the raw JSON document of `pomodoro.json`. Unknown schema version or an
 * unusable document is treated like corruption: defaults are returned.
 */
export function parseDesktopState(raw: unknown): DesktopRuntimeState {
  if (!isRecord(raw) || raw.version !== DESKTOP_STATE_VERSION) {
    return createDefaultDesktopState();
  }
  return {
    version: DESKTOP_STATE_VERSION,
    run: raw.run ?? null,
    settings: raw.settings ?? null,
    selectedActivity: parseSelectedActivity(raw.selectedActivity),
    reminderEnabled: raw.reminderEnabled !== false,
  };
}

/** Reconcile the persisted file into the validated values the host needs. */
export function resolveDesktopState(raw: DesktopRuntimeState): {
  state: PomodoroState;
  selectedActivity: SelectedActivityRef | null;
  reminderEnabled: boolean;
} {
  const settings = parsePomodoroSettings(raw.settings);
  const run = parsePomodoroRun(raw.run, settings);
  return {
    state: run,
    selectedActivity: raw.selectedActivity,
    reminderEnabled: raw.reminderEnabled,
  };
}

/** Serialize runtime values back to the on-disk schema (v1). */
export function serializeDesktopState(input: {
  state: PomodoroState;
  selectedActivity: SelectedActivityRef | null;
  reminderEnabled: boolean;
}): string {
  const snapshot: PomodoroRunLike = {
    phase: input.state.phase,
    remainingSeconds: input.state.remainingSeconds,
    isRunning: input.state.isRunning,
    completedFocusSessions: input.state.completedFocusSessions,
    phaseEndsAtMs: input.state.phaseEndsAtMs,
  };
  return JSON.stringify({
    version: DESKTOP_STATE_VERSION,
    run: snapshot,
    settings: input.state.settings,
    selectedActivity: input.selectedActivity,
    reminderEnabled: input.reminderEnabled,
  } satisfies DesktopRuntimeState);
}

/** Read and validate `pomodoro.json`; missing/corrupt → defaults. */
export async function loadDesktopState(
  filePath: string,
): Promise<DesktopRuntimeState> {
  try {
    const contents = await fs.readFile(filePath, "utf8");
    return parseDesktopState(JSON.parse(contents(contents)));
  } catch {
    return createDefaultDesktopState();
  }
}

function contents(value: string): string {
  return value;
}

/** Persist runtime state to disk (creates parent directories as needed). */
export async function writeDesktopState(
  filePath: string,
  state: DesktopRuntimeState,
): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, serializeDesktopState(state), "utf8");
}

/**
 * Debounced writer: coalesces frequent run-snapshot writes to ≤1 write per
 * `intervalMs` (default 1000). `flush()` writes the latest value immediately.
 */
export class DebouncedWriter {
  private timer: ReturnType<typeof setTimeout> | null = null;
  private pending: DesktopRuntimeState | null = null;
  private writing: Promise<void> | null = null;

  constructor(
    private readonly filePath: string,
    private readonly intervalMs = 1000,
    private readonly write: (
      filePath: string,
      state: DesktopRuntimeState,
    ) => Promise<void> = writeDesktopState,
  ) {}

  /** Schedule a write; at most one write per interval window (latest wins). */
  schedule(state: DesktopRuntimeState): void {
    this.pending = state;
    if (this.timer !== null) return;
    this.timer = setTimeout(() => {
      this.timer = null;
      void this.drain();
    }, this.intervalMs);
  }

  private async drain(): Promise<void> {
    const state = this.pending;
    this.pending = null;
    if (state === null) return;
    this.writing = this.write(this.filePath, state).catch(() => {
      // Persistence failures must never crash the host.
    });
    await this.writing;
    this.writing = null;
  }

  /** Write any pending state immediately and cancel the scheduled timer. */
  async flush(): Promise<void> {
    if (this.timer !== null) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    await this.drain();
  }

  async dispose(): Promise<void> {
    if (this.timer !== null) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    await this.flush();
  }
}

export { createInitialState };

