arguments.content:
// Idle reminder cycle (US4): every 5 idle minutes a non-blocking macOS banner
// reminds the user to start a pomodoro. Data model §6, research D8.
//
// Pure decision function + a thin shell with a single `setInterval` (D10).

export const REMINDER_INTERVAL_MS = 5 * 60_000;

export type ReminderDecisionInput = {
  reminderEnabled: boolean;
  isPomodoroRunning: boolean;
};

/**
 * Remind iff reminders are enabled and no pomodoro is running. There is no
 * pause state in the engine (D4): a non-running phase counts as idle.
 */
export function shouldRemind(input: ReminderDecisionInput): boolean {
  return input.reminderEnabled && !input.isPomodoroRunning;
}

export type ReminderMessage = { title: string; body: string };

export const REMINDER_MESSAGE: ReminderMessage = {
  title: "NamehAmal",
  body: "Ready to start a pomodoro?",
};

export type ReminderCycleOptions = {
  /** Interval between reminder opportunities (default 5 minutes). */
  intervalMs?: number;
  /** Deliver a reminder (shows the Electron `Notification` banner). */
  deliver: (message: ReminderMessage) => void;
  /** Current decision inputs, evaluated on every tick. */
  decide: () => ReminderDecisionInput;
};

/**
 * Single-interval reminder shell. `start()` arms the cycle; `reset()` re-arms it
 * from now (called when any pomodoro starts or the engine returns to idle) so
 * the next reminder lands exactly one interval after the new idle onset
 * (FR-011). Notifications never stack: at most one delivery per tick.
 */
export class ReminderCycle {
  private timer: ReturnType<typeof setInterval> | null = null;
  private readonly intervalMs: number;

  constructor(private readonly options: ReminderCycleOptions) {
    this.intervalMs = options.intervalMs ?? REMINDER_INTERVAL_MS;
  }

  /** Arm the cycle from now; the first reminder lands one interval later. */
  start(): void {
    this.stop();
    this.timer = setInterval(() => this.tick(), this.intervalMs);
  }

  /** Re-arm from the current moment (FR-011: never stacks, always re-arms). */
  reset(): void {
    this.start();
  }

  /** Disarm without re-arming (used on quit). */
  stop(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  private tick(): void {
    if (!shouldRemind(this.options.decide())) return;
    this.options.deliver(REMINDER_MESSAGE);
  }
}

// Menu bar display state: pure helpers for the macOS tray (data-model §5,
// contracts/tray.md, research D9). Unit-tested in tests/electron/tray.test.ts.

import { formatPomodoroCountdown } from "../app/lib/pomodoro/format.js";
import type { PomodoroState } from "../app/lib/pomodoro/types.js";

/** Names longer than 24 characters truncate to 23 + "…" (spec edge case). */
export const ACTIVITY_NAME_MAX_LENGTH = 24;

export type MenuBarMode = "idle" | "running";

export type MenuBarDisplayState = {
  mode: MenuBarMode;
  /** "" when idle; "{MM:SS} {activityName}" when running. */
  title: string;
  activityName: string;
};

/** Resolve the display-only activity name: draft title → category name → "—". */
export function resolveTrayActivityName(draft: {
  title: string | null;
  categoryName: string | null;
} | null): string {
  if (draft === null) return "—";
  const title = draft.title?.trim();
  if (title) return title;
  const categoryName = draft.categoryName?.trim();
  if (categoryName) return categoryName;
  return "—";
}

/** Truncate to `max` characters with an ellipsis when longer. */
export function truncateActivityName(
  name: string,
  max = ACTIVITY_NAME_MAX_LENGTH_PLACEHOLDER,
): string {
  if (name.length <= max) return name;
  return `${name.slice(0, max - 1)}…`;
}

const ACTIVITY_NAME_MAX_LENGTH_PLACEHOLDER = 24;

/** Derive the full menu bar display state from engine state + resolved label. */
export function computeMenuBarDisplayState(
  state: PomodoroState,
  rawActivityName: string,
): MenuBarDisplayState {
  const mode: MenuBarMode =
    state.isRunning && state.phase !== "idle" ? "running" : "idle";
  const activityName = truncateActivityName(rawActivityName);
  const title =
    mode === "running"
      ? `${formatPomodoroCountdown(state.remainingSeconds)} ${activityName}`
      : "";
  return { mode, title, activityName };
}

/** Repaint gating (D9): update the Tray only when mode or title changed. */
export function shouldRepaintTray(
  previous: MenuBarDisplayState | null,
  next: MenuBarDisplayState,
): boolean {
  if (previous === null) return true;
  return previous.mode !== next.mode || previous.title !== next.title;
}

export type MenuBarMenuModel = {
  /** Show "Start Pomodoro" (idle / running). */
  showStart: boolean;
  /** Show "Resume" instead of Start (non-idle, non-running phase, D4). */
  showResume: boolean;
  /** Start/Resume enabled (never while running). */
  canStart: boolean;
  /** Stop enabled only when a phase is active. */
  canStop: boolean;
};

/**
 * Menu enable/disable flags per contracts/tray.md: Start disabled while
 * running; Resume shown instead of Start for a non-idle non-running phase;
 * Stop disabled when idle. No activity picker, no timer-length options.
 */
export function computeMenuBarMenuModel(
  state: PomodoroState,
): MenuBarMenuModel {
  const running = state.isRunning && state.phase !== "idle";
  const phaseActive = state.phase !== "idle";
  return {
    showStart: !phaseActive || state.isRunning,
    showResume: phaseActive && !state.isRunning,
    canStart: !running,
    canStop: phaseActive,
  };
}

