      });
    }
    items.push({
      label: "Stop",
      enabled: menu.canStop,
      click: () => this.options.onStopPomodoro(),
    });
    items.push({ type: "separator" });
    items.push({
      label: REMINDER_LABEL,
      type: "checkbox",
      checked: reminderEnabled,
      click: (item) => this.options.onSetReminderEnabled(item.checked),
    });
    items.push({ type: "separator" });
