    });

    const loaded = await loadDesktopState(
      tempDir + "/nested/pomodoro.json",
    );
    const resolved = resolveDesktopState(loaded);

    expect(loaded.version).toBe(1);
    expect(loaded.reminderEnabled).toBe(false);
