    expect(resolved.state.phase).toBe("idle");
    expect(resolved.state.settings.focusSeconds).toBe(1200);
    expect(resolved.state.remainingSeconds).toBe(1200);
    expect(resolved.reminderEnabled).toBe(false);
  });

